  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('bread with i',cases['13-18']['analysis'])
  self.assertIn('i my/life',cases['13-37']['analysis'])
  self.assertIn('another kjv_comforter_john',cases['14-16']['analysis'])
  self.assertIn('wesg to he come:fu and ourone/dwelling',cases['14-23']['analysis'])
  self.assertIn('mypl/father greater than ipl',cases['14-28']['analysis'])
  self.assertIn('wesg hence go:opt',cases['14-31']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),4)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
